import 'package:flutter/material.dart';

const _bg=Color(0xFF060A18),_card=Color(0xFF0C1226),_card2=Color(0xFF111A31),_line=Color(0xFF242D49),_muted=Color(0xFF8993AD),_purple=Color(0xFFA72BFF),_green=Color(0xFF28F39A),_blue=Color(0xFF499DFF),_amber=Color(0xFFFFBF55);

Map<String,dynamic> _map(dynamic x)=>x is Map?Map<String,dynamic>.from(x):<String,dynamic>{};
List<Map<String,dynamic>> _list(dynamic x)=>x is List?x.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList():<Map<String,dynamic>>[];
double _num(dynamic x)=>x is num?x.toDouble():double.tryParse((x??0).toString())??0;
String _money(dynamic x){final n=_num(x);return '₺'+n.toStringAsFixed(n%1==0?0:2);}
String _date(dynamic raw){if(raw==null||raw.toString().isEmpty)return '-';final d=DateTime.tryParse(raw.toString())?.toLocal();if(d==null)return raw.toString();String p(int n)=>n.toString().padLeft(2,'0');return p(d.day)+'.'+p(d.month)+'.'+d.year.toString()+' '+p(d.hour)+':'+p(d.minute);}
String _status(String s)=>switch(s){'approved'=>'Onaylı','pending'=>'Bekliyor','rejected'=>'Reddedildi','inactive'=>'Pasif','redeemed'=>'Kullanıldı','cancelled'=>'İptal',_=>s};
Color _statusColor(String s)=>switch(s){'approved'||'redeemed'=>_green,'pending'=>_amber,'rejected'||'cancelled'||'inactive'=>Colors.redAccent,_=>_muted};

Widget _hero(String title,String subtitle,IconData icon,Color color)=>Container(
  padding:const EdgeInsets.all(16),
  decoration:BoxDecoration(gradient:const LinearGradient(colors:[Color(0xFF0C1530),Color(0xFF180A29)]),borderRadius:BorderRadius.circular(22),border:Border.all(color:color.withValues(alpha:.32))),
  child:Row(children:[Container(width:46,height:46,decoration:BoxDecoration(color:color.withValues(alpha:.12),shape:BoxShape.circle),child:Icon(icon,color:color,size:25)),const SizedBox(width:11),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:const TextStyle(color:Colors.white,fontSize:21,fontWeight:FontWeight.w900)),const SizedBox(height:2),Text(subtitle,style:const TextStyle(color:_muted,fontSize:11.5))]))]),
);
Widget _pill(String text,Color color)=>Container(padding:const EdgeInsets.symmetric(horizontal:8,vertical:4),decoration:BoxDecoration(color:color.withValues(alpha:.12),borderRadius:BorderRadius.circular(20),border:Border.all(color:color.withValues(alpha:.28))),child:Text(text,style:TextStyle(color:color,fontSize:9.5,fontWeight:FontWeight.w900)));
Widget _metric(String value,String label,IconData icon,Color color)=>Container(height:90,padding:const EdgeInsets.all(11),decoration:BoxDecoration(color:_card,borderRadius:BorderRadius.circular(17),border:Border.all(color:color.withValues(alpha:.25))),child:Row(children:[Icon(icon,color:color,size:25),const SizedBox(width:9),Expanded(child:Column(mainAxisAlignment:MainAxisAlignment.center,crossAxisAlignment:CrossAxisAlignment.start,children:[Text(value,maxLines:1,overflow:TextOverflow.ellipsis,style:const TextStyle(color:Colors.white,fontSize:19,fontWeight:FontWeight.w900)),Text(label,maxLines:2,style:const TextStyle(color:_muted,fontSize:10.5,fontWeight:FontWeight.w700))]))]));
Widget _empty(String text)=>Container(width:double.infinity,padding:const EdgeInsets.symmetric(vertical:42,horizontal:16),decoration:BoxDecoration(color:_card,borderRadius:BorderRadius.circular(18),border:Border.all(color:_line)),child:Column(children:[const Icon(Icons.inbox_outlined,color:_muted,size:38),const SizedBox(height:8),Text(text,textAlign:TextAlign.center,style:const TextStyle(color:_muted,fontWeight:FontWeight.w700))]));

