  ]));}
  Future<void> _reject(BuildContext context,Map<String,dynamic> b)async{final note=TextEditingController(text:(b['admin_note']??'').toString());final ok=await showDialog<bool>(context:context,builder:(d)=>AlertDialog(title:const Text('Başvuruyu reddet'),content:TextField(controller:note,maxLines:3,decoration:const InputDecoration(labelText:'Red nedeni')),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('Vazgeç')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('Reddet'))]));if(ok==true)await onUpdate(b['id'].toString(),{'approvalStatus':'rejected','isActive':false,'adminNote':note.text.trim()});note.dispose();}
